import { Controller, Get, Post, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '인사 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function intOf(v: unknown, label: string, required: boolean): string | null {
  if (v === undefined || v === null || v === '') {
    if (required) {
      throw invalid(label + ' 값을 입력하세요.');
    }
    return null;
  }
  if (typeof v === 'number' && Number.isSafeInteger(v)) {
    return String(v);
  }
  if (typeof v === 'string' && /^-?\d+$/.test(v.trim())) {
    return v.trim();
  }
  throw invalid(label + ' 값은 정수여야 합니다.');
}

function textOf(v: unknown, label: string, required: boolean, max: number): string | null {
  if (v === undefined || v === null || v === '') {
    if (required) {
      throw invalid(label + ' 값을 입력하세요.');
    }
    return null;
  }
  if (typeof v !== 'string') {
    throw invalid(label + ' 값은 글자여야 합니다.');
  }
  if (required && v.trim() === '') {
    throw invalid(label + ' 값을 입력하세요.');
  }
  if (max > 0 && v.length > max) {
    throw invalid(label + ' 값은 ' + max + '자 이하여야 합니다.');
  }
  return v;
}

function dateOf(v: unknown, label: string): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (typeof v !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(v)) {
    throw invalid(label + ' 값은 YYYY-MM-DD 형식이어야 합니다.');
  }
  return v;
}

function pagingOf(q: Record<string, unknown>): { page: number; size: number } {
  const p = intOf(q['page'], '쪽', false);
  const s = intOf(q['size'], '크기', false);
  const page = p === null ? 0 : Number(p);
  const size = s === null ? DEFAULT_SIZE : Number(s);
  if (page < 0 || size < 1) {
    throw invalid('쪽 또는 크기 값이 올바르지 않습니다.');
  }
  return { page, size: Math.min(size, MAX_SIZE) };
}

@Controller('api/v1')
export class FnSfr01502Controller {
  @Post('/edu-courses')
  @HttpCode(200)
  async createEduCourse(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const courseName = textOf(data['courseName'], '교육과정명', true, 200);
    const description = textOf(data['description'], '과정 설명', false, 0);
    return transaction(async (db) => {
      const rows = await db.query(
        'INSERT INTO edu_course (course_name, description, created_at, updated_at) VALUES (:courseName, :description, now(), now()) RETURNING edu_course_id AS "eduCourseId"',
        { courseName, description },
      );
      return rows[0];
    });
  }

  @Get('/edu-courses')
  async listEduCourses(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = pagingOf(q);
    const courseName = textOf(q['courseName'], '교육과정명', false, 200);
    return transaction(async (db) => {
      const where = "(CAST(:courseName AS text) IS NULL OR course_name LIKE '%' || CAST(:courseName AS text) || '%')";
      const totalRows = await db.query('SELECT COUNT(*) AS "total" FROM edu_course WHERE ' + where, { courseName });
      const items = await db.query(
        'SELECT edu_course_id AS "eduCourseId", course_name AS "courseName", description AS "description" FROM edu_course WHERE ' +
          where +
          ' ORDER BY edu_course_id DESC LIMIT :limit OFFSET :offset',
        { courseName, limit: size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }

  @Post('/edu-sessions')
  @HttpCode(200)
  async createEduSession(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const eduCourseId = intOf(data['eduCourseId'], '교육과정', true);
    const sessionNo = intOf(data['sessionNo'], '차수', true);
    const eduTypeCodeId = intOf(data['eduTypeCodeId'], '교육유형', true);
    const eduMethodCodeId = intOf(data['eduMethodCodeId'], '교육방법', true);
    const startDate = dateOf(data['startDate'], '교육 시작일');
    const endDate = dateOf(data['endDate'], '교육 종료일');
    return transaction(async (db) => {
      const courses = await db.query('SELECT edu_course_id FROM edu_course WHERE edu_course_id = CAST(:eduCourseId AS bigint)', { eduCourseId });
      if (courses.length === 0) {
        throw new ApiError(404, 'EDU_COURSE_NOT_FOUND', '교육과정을 찾을 수 없습니다.');
      }
      const types = await db.query(
        "SELECT edu_code_id FROM edu_code WHERE edu_code_id = CAST(:id AS bigint) AND code_group = 'EDU_TYPE'",
        { id: eduTypeCodeId },
      );
      if (types.length === 0) {
        throw invalid('교육유형이 기준 코드에 없습니다.');
      }
      const methods = await db.query(
        "SELECT edu_code_id FROM edu_code WHERE edu_code_id = CAST(:id AS bigint) AND code_group = 'EDU_METHOD'",
        { id: eduMethodCodeId },
      );
      if (methods.length === 0) {
        throw invalid('교육방법이 기준 코드에 없습니다.');
      }
      if (startDate !== null && endDate !== null) {
        const ok = await db.query('SELECT (CAST(:endDate AS date) >= CAST(:startDate AS date)) AS "ok"', { startDate, endDate });
        if (ok[0]['ok'] !== true) {
          throw invalid('교육 종료일은 시작일 이후여야 합니다.');
        }
      }
      const dup = await db.query(
        'SELECT edu_session_id FROM edu_session WHERE edu_course_id = CAST(:eduCourseId AS bigint) AND session_no = CAST(:sessionNo AS integer)',
        { eduCourseId, sessionNo },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'EDU_SESSION_DUPLICATED', '같은 과정에 같은 차수가 이미 있습니다.');
      }
      const rows = await db.query(
        'INSERT INTO edu_session (edu_course_id, session_no, edu_type_code_id, edu_method_code_id, start_date, end_date, created_at, updated_at) ' +
          'VALUES (CAST(:eduCourseId AS bigint), CAST(:sessionNo AS integer), CAST(:eduTypeCodeId AS bigint), CAST(:eduMethodCodeId AS bigint), CAST(:startDate AS date), CAST(:endDate AS date), now(), now()) ' +
          'RETURNING edu_session_id AS "eduSessionId"',
        { eduCourseId, sessionNo, eduTypeCodeId, eduMethodCodeId, startDate, endDate },
      );
      return rows[0];
    });
  }

  @Get('/edu-sessions')
  async listEduSessions(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = pagingOf(q);
    const eduCourseId = intOf(q['eduCourseId'], '교육과정', false);
    return transaction(async (db) => {
      const where = '(CAST(:eduCourseId AS bigint) IS NULL OR edu_course_id = CAST(:eduCourseId AS bigint))';
      const totalRows = await db.query('SELECT COUNT(*) AS "total" FROM edu_session WHERE ' + where, { eduCourseId });
      const items = await db.query(
        'SELECT edu_session_id AS "eduSessionId", edu_course_id AS "eduCourseId", session_no AS "sessionNo", edu_type_code_id AS "eduTypeCodeId", ' +
          'edu_method_code_id AS "eduMethodCodeId", start_date AS "startDate", end_date AS "endDate" FROM edu_session WHERE ' +
          where +
          ' ORDER BY edu_course_id, session_no LIMIT :limit OFFSET :offset',
        { eduCourseId, limit: size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }

  @Post('/edu-attendees')
  @HttpCode(200)
  async createEduAttendee(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const eduSessionId = intOf(data['eduSessionId'], '교육차수', true);
    const employeeId = intOf(data['employeeId'], '교육대상자', true);
    return transaction(async (db) => {
      const sessions = await db.query('SELECT edu_session_id FROM edu_session WHERE edu_session_id = CAST(:eduSessionId AS bigint)', { eduSessionId });
      if (sessions.length === 0) {
        throw new ApiError(404, 'EDU_SESSION_NOT_FOUND', '교육 차수를 찾을 수 없습니다.');
      }
      const emps = await db.query('SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)', { employeeId });
      if (emps.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '임직원을 찾을 수 없습니다.');
      }
      const dup = await db.query(
        'SELECT edu_attendee_id FROM edu_attendee WHERE edu_session_id = CAST(:eduSessionId AS bigint) AND employee_id = CAST(:employeeId AS bigint)',
        { eduSessionId, employeeId },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'EDU_ATTENDEE_DUPLICATED', '이미 해당 차수에 등록된 교육대상자입니다.');
      }
      const rows = await db.query(
        'INSERT INTO edu_attendee (edu_session_id, employee_id, created_at, updated_at) VALUES (CAST(:eduSessionId AS bigint), CAST(:employeeId AS bigint), now(), now()) ' +
          'RETURNING edu_attendee_id AS "eduAttendeeId"',
        { eduSessionId, employeeId },
      );
      return rows[0];
    });
  }

  @Get('/edu-attendees')
  async listEduAttendees(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = pagingOf(q);
    const eduSessionId = intOf(q['eduSessionId'], '교육차수', true);
    return transaction(async (db) => {
      const where = 'edu_session_id = CAST(:eduSessionId AS bigint)';
      const totalRows = await db.query('SELECT COUNT(*) AS "total" FROM edu_attendee WHERE ' + where, { eduSessionId });
      const items = await db.query(
        'SELECT edu_attendee_id AS "eduAttendeeId", employee_id AS "employeeId" FROM edu_attendee WHERE ' +
          where +
          ' ORDER BY edu_attendee_id LIMIT :limit OFFSET :offset',
        { eduSessionId, limit: size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }

  @Delete('/edu-attendees/:eduAttendeeId')
  async deleteEduAttendee(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const eduAttendeeId = intOf(req.params['eduAttendeeId'], '교육대상자 ID', true);
    return transaction(async (db) => {
      const count = await db.execute('DELETE FROM edu_attendee WHERE edu_attendee_id = CAST(:eduAttendeeId AS bigint)', { eduAttendeeId });
      if (count === 0) {
        throw new ApiError(404, 'EDU_ATTENDEE_NOT_FOUND', '교육대상자를 찾을 수 없습니다.');
      }
      return {};
    });
  }

  @Post('/edu-result-reports')
  @HttpCode(200)
  async createEduResultReport(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const eduSessionId = intOf(data['eduSessionId'], '교육차수', true);
    const title = textOf(data['title'], '보고 제목', false, 200);
    const reportContent = textOf(data['reportContent'], '보고 내용', false, 0);
    const attachmentId = intOf(data['attachmentId'], '첨부파일', false);
    return transaction(async (db) => {
      const sessions = await db.query('SELECT edu_session_id FROM edu_session WHERE edu_session_id = CAST(:eduSessionId AS bigint)', { eduSessionId });
      if (sessions.length === 0) {
        throw new ApiError(404, 'EDU_SESSION_NOT_FOUND', '교육 차수를 찾을 수 없습니다.');
      }
      if (attachmentId !== null) {
        const files = await db.query('SELECT attachment_id FROM attachment WHERE attachment_id = CAST(:attachmentId AS bigint)', { attachmentId });
        if (files.length === 0) {
          throw invalid('첨부파일을 찾을 수 없습니다.');
        }
      }
      const rows = await db.query(
        'INSERT INTO edu_result_report (edu_session_id, attachment_id, title, report_content, created_at, updated_at) ' +
          'VALUES (CAST(:eduSessionId AS bigint), CAST(:attachmentId AS bigint), :title, :reportContent, now(), now()) ' +
          'RETURNING edu_result_report_id AS "eduResultReportId"',
        { eduSessionId, attachmentId, title, reportContent },
      );
      return rows[0];
    });
  }

  @Get('/edu-result-reports')
  async listEduResultReports(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const { page, size } = pagingOf(q);
    const eduSessionId = intOf(q['eduSessionId'], '교육차수', false);
    return transaction(async (db) => {
      const where = '(CAST(:eduSessionId AS bigint) IS NULL OR edu_session_id = CAST(:eduSessionId AS bigint))';
      const totalRows = await db.query('SELECT COUNT(*) AS "total" FROM edu_result_report WHERE ' + where, { eduSessionId });
      const items = await db.query(
        'SELECT edu_result_report_id AS "eduResultReportId", edu_session_id AS "eduSessionId", title AS "title", report_content AS "reportContent" FROM edu_result_report WHERE ' +
          where +
          ' ORDER BY edu_result_report_id DESC LIMIT :limit OFFSET :offset',
        { eduSessionId, limit: size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }
}

