import { useState } from 'react';
import {
  call, useData, Band, DataTable, Pager, Drawer, Filters, Form, Field, TextInput, NumberInput, DateInput,
  LookupSelect, RefName, DateText, Tiles,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const EMPTY: Page = { items: [], page: 0, size: 20, total: 0 };

export default function FnSfr01502Page({ role, notify }: PageProps) {
  const [drawer, setDrawer] = useState('');
  const [form, setForm] = useState<Row>({});
  const [courseId, setCourseId] = useState<number | null>(null);
  const [sessionId, setSessionId] = useState<number | null>(null);
  const [nameInput, setNameInput] = useState('');
  const [courseName, setCourseName] = useState('');
  const [coursePage, setCoursePage] = useState(0);
  const [sessionPage, setSessionPage] = useState(0);
  const [attendeePage, setAttendeePage] = useState(0);
  const [reportPage, setReportPage] = useState(0);

  const courses = useData<Page>(
    () => call<Page>('GET', '/edu-courses', role, undefined, { courseName, page: coursePage, size: 10 }),
    [courseName, coursePage],
  );
  const sessions = useData<Page>(
    () => call<Page>('GET', '/edu-sessions', role, undefined, { eduCourseId: courseId ?? '', page: sessionPage, size: 10 }),
    [courseId, sessionPage],
  );
  const attendees = useData<Page>(
    () => (sessionId === null
      ? Promise.resolve(EMPTY)
      : call<Page>('GET', '/edu-attendees', role, undefined, { eduSessionId: sessionId, page: attendeePage, size: 10 })),
    [sessionId, attendeePage],
  );
  const reports = useData<Page>(
    () => call<Page>('GET', '/edu-result-reports', role, undefined, { eduSessionId: sessionId ?? '', page: reportPage, size: 10 }),
    [sessionId, reportPage],
  );

  const open = (name: string, init: Row = {}) => {
    setForm(init);
    setDrawer(name);
  };
  const set = (key: string, value: unknown) => setForm((f) => ({ ...f, [key]: value }));
  const close = () => setDrawer('');
  const missing = (labels: [string, string][]) => {
    for (const [key, label] of labels) {
      const v = form[key];
      if (v === undefined || v === null || v === '') {
        throw new Error(label + ' 값을 입력하세요.');
      }
    }
  };

  const submitCourse = async () => {
    missing([['courseName', '교육과정명']]);
    await call('POST', '/edu-courses', role, { courseName: form.courseName, description: form.description });
    notify('교육과정을 등록했습니다.');
    close();
    courses.reload();
  };
  const submitSession = async () => {
    missing([['eduCourseId', '교육과정'], ['sessionNo', '차수'], ['eduTypeCodeId', '교육유형'], ['eduMethodCodeId', '교육방법']]);
    await call('POST', '/edu-sessions', role, {
      eduCourseId: form.eduCourseId,
      sessionNo: form.sessionNo,
      eduTypeCodeId: form.eduTypeCodeId,
      eduMethodCodeId: form.eduMethodCodeId,
      startDate: form.startDate,
      endDate: form.endDate,
    });
    notify('교육 차수를 등록했습니다.');
    close();
    sessions.reload();
  };
  const submitAttendee = async () => {
    missing([['eduSessionId', '교육차수'], ['employeeId', '교육대상자']]);
    await call('POST', '/edu-attendees', role, { eduSessionId: form.eduSessionId, employeeId: form.employeeId });
    notify('교육대상자를 등록했습니다.');
    close();
    attendees.reload();
  };
  const submitReport = async () => {
    missing([['eduSessionId', '교육차수']]);
    await call('POST', '/edu-result-reports', role, {
      eduSessionId: form.eduSessionId,
      title: form.title,
      reportContent: form.reportContent,
      attachmentId: form.attachmentId,
    });
    notify('교육결과 보고를 등록했습니다.');
    close();
    reports.reload();
  };
  const removeAttendee = async (row: Row) => {
    try {
      await call('DELETE', '/edu-attendees/' + String(row.eduAttendeeId), role);
      notify('교육대상자를 삭제했습니다.');
      attendees.reload();
    } catch (e) {
      notify(e instanceof Error ? e.message : '삭제하지 못했습니다.');
    }
  };

  const c = courses.data ?? EMPTY;
  const s = sessions.data ?? EMPTY;
  const a = attendees.data ?? EMPTY;
  const r = reports.data ?? EMPTY;

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>현황</h2>
        <Tiles items={[
          ['교육과정', c.total],
          ['교육 차수', s.total],
          ['교육대상자', a.total],
          ['결과 보고', r.total],
        ]} />
      </section>

      <section className='box span-6'>
        <h2>교육과정</h2>
        <Filters
          onSearch={() => { setCoursePage(0); setCourseName(nameInput); }}
          onReset={() => { setNameInput(''); setCourseName(''); setCoursePage(0); }}
        >
          <Field label='교육과정명'>
            <TextInput value={nameInput} onChange={setNameInput} />
          </Field>
        </Filters>
        <Band total={c.total}>
          <button onClick={() => open('course')}>교육과정 등록</button>
        </Band>
        <DataTable
          rows={c.items}
          onRowClick={(row) => { setCourseId(Number(row.eduCourseId)); setSessionId(null); setSessionPage(0); }}
          columns={[
            { key: 'courseName', label: '교육과정명' },
            { key: 'description', label: '과정 설명' },
          ]}
        />
        <Pager page={c.page} size={c.size} total={c.total} onPage={setCoursePage} />
      </section>

      <section className='box span-6'>
        <h2>교육 차수</h2>
        <Band total={s.total}>
          <button onClick={() => open('session', { eduCourseId: courseId ?? '' })}>차수 등록</button>
        </Band>
        <DataTable
          rows={s.items}
          onRowClick={(row) => { setSessionId(Number(row.eduSessionId)); setAttendeePage(0); setReportPage(0); }}
          columns={[
            { key: 'eduCourseId', label: '교육과정', render: (row) => <RefName table='edu_course' role={role} value={row.eduCourseId} /> },
            { key: 'sessionNo', label: '차수' },
            { key: 'eduTypeCodeId', label: '교육유형', render: (row) => <RefName table='edu_code' role={role} value={row.eduTypeCodeId} /> },
            { key: 'eduMethodCodeId', label: '교육방법', render: (row) => <RefName table='edu_code' role={role} value={row.eduMethodCodeId} /> },
            { key: 'startDate', label: '교육 시작일', render: (row) => <DateText value={row.startDate} /> },
            { key: 'endDate', label: '교육 종료일', render: (row) => <DateText value={row.endDate} /> },
          ]}
        />
        <Pager page={s.page} size={s.size} total={s.total} onPage={setSessionPage} />
      </section>

      <section className='box span-6'>
        <h2>교육대상자</h2>
        <Band total={a.total}>
          <button onClick={() => open('attendee', { eduSessionId: sessionId ?? '' })}>교육대상자 등록</button>
        </Band>
        <DataTable
          rows={a.items}
          empty='교육 차수를 선택하세요.'
          columns={[
            { key: 'employeeId', label: '교육대상자', render: (row) => <RefName table='employee' role={role} value={row.employeeId} /> },
            { key: 'eduAttendeeId', label: '삭제', render: (row) => <button onClick={(e) => { e.stopPropagation(); removeAttendee(row); }}>삭제</button> },
          ]}
        />
        <Pager page={a.page} size={a.size} total={a.total} onPage={setAttendeePage} />
      </section>

      <section className='box span-6'>
        <h2>교육결과 보고</h2>
        <Band total={r.total}>
          <button onClick={() => open('report', { eduSessionId: sessionId ?? '' })}>결과 보고 등록</button>
        </Band>
        <DataTable
          rows={r.items}
          columns={[
            { key: 'eduSessionId', label: '교육차수' },
            { key: 'title', label: '보고 제목' },
            { key: 'reportContent', label: '보고 내용' },
          ]}
        />
        <Pager page={r.page} size={r.size} total={r.total} onPage={setReportPage} />
      </section>

      {drawer === 'course' && (
        <Drawer title='교육과정 등록' onClose={close}>
          <Form onSubmit={submitCourse} submit='등록'>
            <Field label='교육과정명' required wide>
              <TextInput value={form.courseName} onChange={(v) => set('courseName', v)} />
            </Field>
            <Field label='과정 설명' wide>
              <TextInput multiline value={form.description} onChange={(v) => set('description', v)} />
            </Field>
          </Form>
        </Drawer>
      )}

      {drawer === 'session' && (
        <Drawer title='교육 차수 등록' onClose={close}>
          <Form onSubmit={submitSession} submit='등록'>
            <Field label='교육과정' required>
              <LookupSelect table='edu_course' role={role} value={form.eduCourseId} onChange={(v) => set('eduCourseId', v)} />
            </Field>
            <Field label='차수' required>
              <NumberInput value={form.sessionNo} onChange={(v) => set('sessionNo', v)} />
            </Field>
            <Field label='교육유형' required>
              <LookupSelect table='edu_code' role={role} value={form.eduTypeCodeId} onChange={(v) => set('eduTypeCodeId', v)} />
            </Field>
            <Field label='교육방법' required>
              <LookupSelect table='edu_code' role={role} value={form.eduMethodCodeId} onChange={(v) => set('eduMethodCodeId', v)} />
            </Field>
            <Field label='교육 시작일'>
              <DateInput value={form.startDate} onChange={(v) => set('startDate', v)} />
            </Field>
            <Field label='교육 종료일'>
              <DateInput value={form.endDate} onChange={(v) => set('endDate', v)} />
            </Field>
          </Form>
        </Drawer>
      )}

      {drawer === 'attendee' && (
        <Drawer title='교육대상자 등록' onClose={close}>
          <Form onSubmit={submitAttendee} submit='등록'>
            <Field label='교육차수' required>
              <NumberInput value={form.eduSessionId} onChange={(v) => set('eduSessionId', v)} />
            </Field>
            <Field label='교육대상자' required>
              <LookupSelect table='employee' role={role} value={form.employeeId} onChange={(v) => set('employeeId', v)} />
            </Field>
          </Form>
        </Drawer>
      )}

      {drawer === 'report' && (
        <Drawer title='교육결과 보고 등록' onClose={close}>
          <Form onSubmit={submitReport} submit='등록'>
            <Field label='교육차수' required>
              <NumberInput value={form.eduSessionId} onChange={(v) => set('eduSessionId', v)} />
            </Field>
            <Field label='보고 제목' wide>
              <TextInput value={form.title} onChange={(v) => set('title', v)} />
            </Field>
            <Field label='보고 내용' wide>
              <TextInput multiline value={form.reportContent} onChange={(v) => set('reportContent', v)} />
            </Field>
            <Field label='첨부파일'>
              <LookupSelect table='attachment' role={role} value={form.attachmentId} onChange={(v) => set('attachmentId', v)} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
